alter table public.buildpulse_incidents add column if not exists acknowledged_at timestamptz, add column if not exists acknowledged_by uuid references auth.users(id), add column if not exists resolution_note text;
create table if not exists public.buildpulse_incident_events(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.buildpulse_incidents(id) on delete cascade,actor_user_id uuid references auth.users(id),event_type text not null check(event_type in ('created','acknowledged','investigating','mitigated','resolved','reopened','assigned','note')),note text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.buildpulse_incident_events enable row level security;revoke all on public.buildpulse_incident_events from anon,authenticated;grant all on public.buildpulse_incident_events to service_role;
create index if not exists idx_bp_incident_events_incident on public.buildpulse_incident_events(incident_id,created_at desc);